#pragma once

#include <KDecoration3/DecoratedWindow>

#include <QColor>
#include <QString>

namespace KWin
{
namespace Decoration
{

/**
 * Which palette the Kinetic decoration uses.
 *
 * Dark / Light read the colors generated by the Noctalia "kineticwe" template;
 * Auto follows the shared color scheme (live recolor).
 */
enum class KineticTheme {
    Auto,
    Dark,
    Light,
};

inline KineticTheme kineticThemeFromString(const QString &theme)
{
    const QString t = theme.toLower();
    if (t == QLatin1String("light")) {
        return KineticTheme::Light;
    }
    if (t == QLatin1String("auto")) {
        return KineticTheme::Auto;
    }
    // "dark", the metadata default and any older/unknown value map to the dark
    // variant so the compiled-in default is actually dark.
    return KineticTheme::Dark;
}

/**
 * Colors produced by the Noctalia "kineticwe" template for one variant.
 */
struct KineticColors {
    QColor frame;
    QColor titleBar;
    QColor foreground;
    QColor outline;

    bool isValid() const
    {
        return frame.isValid() || titleBar.isValid();
    }
};

/**
 * Path of the colors file written by the Noctalia "kineticwe" template, in the
 * user's real config home (the compositor's config root is redirected).
 */
QString kineticColorsPath();

/**
 * Load the [Dark]/[Light] colors written by the template. Returns an invalid
 * KineticColors when the template has not been applied or the file is missing,
 * in which case callers should fall back to the system color scheme.
 */
KineticColors loadKineticColors(KineticTheme theme);

/**
 * Resolve a color for a role: template colors when available, otherwise the
 * decorated window's color scheme.
 */
QColor kineticColor(const KineticColors &colors, const KDecoration3::DecoratedWindow *window, KDecoration3::ColorRole role, bool active);

}
}
